#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 60
#define MAX_STEPS 200

static const int rule110[8] = {0,1,1,1,0,1,1,0};

int main(int argc, char *argv[]) {
    if (argc < 3) { puts("INVALID_INPUT"); return 0; }
    const char *init = argv[1];
    size_t len = strlen(init);
    if (len == 0 || len > MAX_LEN) { puts("INVALID_INPUT"); return 0; }
    for (size_t i=0;i<len;i++) if (init[i]!='0' && init[i]!='1') { puts("INVALID_INPUT"); return 0; }
    char *endptr; long steps = strtol(argv[2], &endptr, 10);
    if (*endptr!='\0') { puts("INVALID_INPUT"); return 0; }
    if (steps<0) steps=0; if (steps>MAX_STEPS) steps=MAX_STEPS;
    static char rows[MAX_STEPS+1][MAX_LEN+1];
    memcpy(rows[0], init, len); rows[0][len]='\0';
    for (int gen=0; gen<steps; ++gen) {
        for (size_t i=0;i<len;i++) putchar(rows[gen][i]);
        putchar('\n');
        if (gen+1==steps) break;
        for (size_t i=0;i<len;i++) {
            int left = (i==0)?0:rows[gen][i-1]-'0';
            int center = rows[gen][i]-'0';
            int right = (i+1==len)?0:rows[gen][i+1]-'0';
            int idx = (left<<2)|(center<<1)|right;
            rows[gen+1][i] = rule110[idx] + '0';
        }
        rows[gen+1][len]='\0';
    }
    return 0;
}
